import{c as t,Q as n,j as s,m as i}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Configuring extensions","description":"","frontmatter":{},"headers":[],"relativePath":"user/advanced/configuring-extensions.md","filePath":"user/advanced/configuring-extensions.md"}'),a={name:"user/advanced/configuring-extensions.md"};function o(r,e,h,l,d,g){return n(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="configuring-extensions" tabindex="-1">Configuring extensions <a class="header-anchor" href="#configuring-extensions" aria-label="Permalink to &quot;Configuring extensions&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers setting up an installed extension for their events.</p><p>An extension can have settings at two levels: settings for this computer, shared by every event, and settings for one event. This page covers both, and switching an extension on for an event.</p><h2 id="using-an-extension-in-an-event" tabindex="-1">Using an extension in an event <a class="header-anchor" href="#using-an-extension-in-an-event" aria-label="Permalink to &quot;Using an extension in an event&quot;">​</a></h2><p>An installed extension does nothing in an event until the event switches it on:</p><ol><li>Open the event and click <strong>Event details</strong>.</li><li>Go to the <strong>Extensions</strong> tab. Every installed extension is listed with a switch.</li><li>Switch on the ones this event should use. An extension with per-event settings shows them as soon as it&#39;s on.</li><li>Click <strong>Save</strong>.</li></ol><p>Its tile then appears on the event&#39;s dashboard. Like any tile, you can hide it or move it with <strong>Edit dashboard</strong>. See <a href="./../running-the-event/dashboard">The event dashboard</a>.</p><p>Some tiles only work while the event is running, for example one that fetches entries from elsewhere on the day. Before the event starts and after it finishes, such a tile shows a placeholder and fetches nothing.</p><h2 id="the-two-levels-of-settings" tabindex="-1">The two levels of settings <a class="header-anchor" href="#the-two-levels-of-settings" aria-label="Permalink to &quot;The two levels of settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Where</th><th>Applies to</th><th>Typical use</th></tr></thead><tbody><tr><td><strong>This computer</strong></td><td>The <strong>Extensions</strong> page: the extension&#39;s settings button</td><td>Every event on this computer</td><td>An account, a key, an address the extension connects to</td></tr><tr><td><strong>This event</strong></td><td><strong>Event details → Extensions</strong>, under the extension&#39;s switch</td><td>This event only</td><td>Which spreadsheet, which classes, a colour for this event</td></tr></tbody></table><p>Which settings an extension has, at either level, is up to whoever wrote it. Each is a switch, a text box, a number or a choice of colour, with the extension&#39;s own label.</p><h3 id="settings-for-this-computer" tabindex="-1">Settings for this computer <a class="header-anchor" href="#settings-for-this-computer" aria-label="Permalink to &quot;Settings for this computer&quot;">​</a></h3><p>On the <strong>Extensions</strong> page, open the extension&#39;s settings, change them, and click <strong>Save</strong> (<em>Settings saved</em>). They apply to every event straight away; reload an open dashboard to be sure a tile has picked them up.</p><h3 id="settings-for-an-event" tabindex="-1">Settings for an event <a class="header-anchor" href="#settings-for-an-event" aria-label="Permalink to &quot;Settings for an event&quot;">​</a></h3><p>In <strong>Event details → Extensions</strong>, change the fields under the extension&#39;s switch, then <strong>Save</strong> the event details. They&#39;re saved with the event, so they go with it in a backup and when it&#39;s moved to another computer, unlike the settings for this computer.</p><h2 id="copying-settings-to-another-event" tabindex="-1">Copying settings to another event <a class="header-anchor" href="#copying-settings-to-another-event" aria-label="Permalink to &quot;Copying settings to another event&quot;">​</a></h2><p>There&#39;s no copy button. A <a href="./../event-setup/create-event#duplicating-an-event">duplicated event</a> keeps its extensions switched on with the same settings; otherwise, switch the extension on in the new event and fill its settings in again.</p><h2 id="getting-back-to-the-defaults" tabindex="-1">Getting back to the defaults <a class="header-anchor" href="#getting-back-to-the-defaults" aria-label="Permalink to &quot;Getting back to the defaults&quot;">​</a></h2><p>There&#39;s no reset button, and settings are kept on purpose:</p><ul><li><strong>An event&#39;s settings</strong> start from the extension&#39;s own defaults the first time you switch it on. Switching it off and on again keeps what you had set.</li><li><strong>Settings for this computer</strong> are kept when you remove the extension, so installing it again, or a newer version, brings them back.</li></ul><p>To go back to the defaults, set each field back by hand.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./installing-extensions">Installing extensions</a></li><li><a href="./../running-the-event/dashboard">The event dashboard</a></li><li><a href="./../event-setup/create-event#extensions">Creating an event</a></li></ul>',23)])])}const p=t(a,[["render",o]]);export{u as __pageData,p as default};
